<template><details class="community-product-editor" @toggle="opened"><summary>Liên kết sản phẩm từ gian hàng của tôi (tối đa 3)</summary><p class="community-hint">Chỉ sản phẩm còn công khai của gian hàng được duyệt. Bài chia sẻ vẫn hoạt động khi không liên kết sản phẩm.</p><p v-if="loading" role="status">Đang tải sản phẩm…</p><p v-if="error" role="alert">{{ error }} <button type="button" class="button button-outline" @click="load">Thử lại</button></p><p v-if="ready&&!loading&&!data.totalElements" class="community-hint">Chưa có sản phẩm đủ điều kiện. Gian hàng cần hoạt động, có hồ sơ Seller đã duyệt và sản phẩm đang công khai.</p>
  <form v-if="ready" @submit.prevent="save"><div v-for="product in data.content" :key="product.id" class="community-product-choice"><input :id="'linked-'+product.id" v-model="selected" type="checkbox" :value="product.id" :disabled="busy||!selected.includes(product.id)&&selected.length>=3"/><label :for="'linked-'+product.id">{{ product.name }}</label></div><nav v-if="data.totalPages>1" class="community-actions" aria-label="Phân trang sản phẩm để liên kết"><button type="button" class="button button-outline" :disabled="!page||loading||busy" @click="page--;load()">Trước</button><span>{{ page+1 }} / {{ data.totalPages }}</span><button type="button" class="button button-outline" :disabled="page+1>=data.totalPages||loading||busy" @click="page++;load()">Sau</button></nav><p>{{ selected.length }} / 3 sản phẩm đã chọn</p><button class="button button-outline" :disabled="busy||loading">{{ busy?'Đang lưu…':'Lưu sản phẩm liên kết' }}</button></form>
</details></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {marketplaceRequest as request} from '../../services/marketplace.js';const props=defineProps({post:{type:Object,required:true},products:{type:Array,default:()=>[]}}),emit=defineEmits(['saved']);const selected=ref(props.products.map(p=>p.id)),page=ref(0),data=ref({content:[],totalPages:0,totalElements:0}),ready=ref(false),loading=ref(false),busy=ref(false),error=ref('');let generation=0;
watch(()=>props.products,p=>{if(!busy.value)selected.value=p.map(p=>p.id);});
async function load(){const ticket=++generation;loading.value=true;error.value='';try{const result=await request('/account/community/products?page='+page.value);if(ticket===generation){data.value=result;ready.value=true;}}catch(e){if(ticket===generation)error.value=e.message;}finally{if(ticket===generation)loading.value=false;}}
function opened(e){if(e.target.open&&!ready.value)load();}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await request('/account/community/posts/'+props.post.id+'/products','PUT',{productIds:selected.value,revision:props.post.revision});emit('saved');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onBeforeUnmount(()=>generation++);
</script>
